$ArtifactRoot = Join-Path $PackageRoot 'VSCode-win32-x64'
$ContentRoot = Join-Path $PSScriptRoot 'release-content'
$ManifestPath = Join-Path $PSScriptRoot 'win32-x64-runtime-payload-manifest.json'
$ReleaseContentManifestPath = Join-Path $ContentRoot 'manifest.json'
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false, $true)
$DirectorySeparatorChar = [IO.Path]::DirectorySeparatorChar
. (Join-Path $PSScriptRoot 'release-content-manifest.ps1')
$ReleaseContentManifest = Get-ReleaseContentManifest -ManifestPath $ReleaseContentManifestPath -ContentRoot $ContentRoot

function Write-Utf8NoBomText { param([string]$Path,[string]$Text) [IO.File]::WriteAllText($Path,$Text,$Utf8NoBom) }
function Write-Utf8NoBomJson { param([string]$Path,$Value) Write-Utf8NoBomText $Path ($Value | ConvertTo-Json -Depth 32) }
function Read-Utf8NoBomText {
    param([string]$Path)
    $bytes=[IO.File]::ReadAllBytes($Path)
    if($bytes.Length -eq 0 -or ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191)){throw "Expected non-empty UTF8 no-BOM text: $Path"}
    try { return $Utf8NoBom.GetString($bytes) } catch { throw "Invalid UTF8 text: $Path" }
}
function Read-Utf8NoBomTextAllowEmpty {
    param([string]$Path)
    $bytes=[IO.File]::ReadAllBytes($Path);if($bytes.Length -eq 0){return ''};if($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191){throw "Expected UTF8 no-BOM text: $Path"};try{return $Utf8NoBom.GetString($bytes)}catch{throw "Invalid UTF8 text: $Path"}
}
function Read-ZipEntryStrictUtf8NoBom {
    param([IO.Compression.ZipArchiveEntry]$Entry)
    $s=$Entry.Open();$m=New-Object IO.MemoryStream
    try {$s.CopyTo($m);$bytes=$m.ToArray();if($bytes.Length -eq 0 -or ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191)){throw "Expected non-empty UTF8 no-BOM ZIP text: $($Entry.FullName)"};try{return $Utf8NoBom.GetString($bytes)}catch{throw "Invalid UTF8 ZIP text: $($Entry.FullName)"}}finally{$m.Dispose();$s.Dispose()}
}
function Get-Sha256Stream { param([IO.Stream]$Stream) $h=New-Object Security.Cryptography.SHA256Managed;try{([BitConverter]::ToString($h.ComputeHash($Stream))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()} }
function Get-Sha256File { param([string]$Path) $s=[IO.File]::OpenRead($Path);try{Get-Sha256Stream $s}finally{$s.Dispose()} }
function Get-NormalizedArchivePath {
    param([string]$Path)
    if([string]::IsNullOrWhiteSpace($Path) -or $Path -match '^[\\/]' -or $Path -match '^[A-Za-z]:'){throw "Unsafe archive path: $Path"}
    $n=$Path.Replace('\','/').Trim('/')
    $badSegments=@($n.Split('/') | Where-Object { $_ -eq '' -or $_ -eq '.' -or $_ -eq '..' })
    if($n -eq '' -or $badSegments.Count -gt 0){throw "Unsafe archive path: $Path"}
    Assert-ReleaseContentWindowsSafePathSegments -Path $n -Purpose 'archive'
    return $n
}
function Assert-CanonicalArchiveEntryPath { param([string]$Path) $n=Get-NormalizedArchivePath $Path;if($Path.IndexOf([char]92) -ge 0 -or $Path -cne $n){throw "Non-canonical archive path: $Path"};$n }
function Assert-ContainedPath { param([string]$Root,[string]$Path) $trim=@($DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$r=[IO.Path]::GetFullPath($Root).TrimEnd([char[]]$trim)+$DirectorySeparatorChar;$p=[IO.Path]::GetFullPath($Path);if(-not $p.StartsWith($r,[StringComparison]::OrdinalIgnoreCase)){throw "Path escapes root: $Path"};$p }
function Test-SamePhysicalPath { param([string]$Left,[string]$Right) if([string]::IsNullOrWhiteSpace($Left) -or [string]::IsNullOrWhiteSpace($Right)){return $false};[string]::Equals([IO.Path]::GetFullPath($Left),[IO.Path]::GetFullPath($Right),[StringComparison]::OrdinalIgnoreCase) }
function Assert-ImmediateChild { param([string]$Root,[string]$Path) $trim=@($DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$p=Assert-ContainedPath $Root $Path;if(-not(Test-SamePhysicalPath ([IO.Path]::GetDirectoryName($p)).TrimEnd([char[]]$trim) ([IO.Path]::GetFullPath($Root)).TrimEnd([char[]]$trim))){throw "Path is not an immediate child: $Path"};$p }
function Assert-NotReparsePoint { param([string]$Path) $i=Get-Item -LiteralPath $Path -Force;if(($i.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw "Reparse point is forbidden: $Path"};$i }
function Assert-NoReparsePointsInTree {
    param([string]$Root)
    $rootInfo=New-Object IO.DirectoryInfo($Root);if(-not $rootInfo.Exists){throw "Directory does not exist: $Root"};$pending=New-Object Collections.Generic.Stack[IO.DirectoryInfo];$pending.Push($rootInfo)
    while($pending.Count -gt 0){$current=$pending.Pop();if(($current.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw "Reparse point is forbidden: $($current.FullName)"};foreach($child in $current.GetFileSystemInfos()){if(($child.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw "Reparse point is forbidden: $($child.FullName)"};if($child -is [IO.DirectoryInfo]){$pending.Push([IO.DirectoryInfo]$child)}}}
}
function Read-ExactBytes { param([IO.Stream]$Stream,[int]$Count) $b=New-Object byte[] $Count;$o=0;while($o -lt $Count){$r=$Stream.Read($b,$o,$Count-$o);if($r -le 0){throw 'Truncated PE file.'};$o+=$r};$b }
function Assert-X64PeStream {
    param([IO.Stream]$Stream)
    $copy=New-Object IO.MemoryStream
    try {
        $Stream.CopyTo($copy);$b=$copy.ToArray();if($b.Length -lt 64 -or $b[0] -ne 77 -or $b[1] -ne 90){throw 'Expected PE MZ header.'}
        $off=[BitConverter]::ToInt32($b,60);if($off -lt 0 -or $off -gt $b.Length-6){throw 'Invalid PE header offset.'}
        if($b[$off] -ne 80 -or $b[$off+1] -ne 69 -or $b[$off+2] -ne 0 -or $b[$off+3] -ne 0){throw 'Expected PE signature.'}
        if([BitConverter]::ToUInt16($b,$off+4) -ne 0x8664){throw 'Expected x64 PE machine.'}
    } finally {$copy.Dispose()}
}
function Assert-X64PeFile { param([string]$Path) $s=[IO.File]::OpenRead($Path);try{Assert-X64PeStream $s}finally{$s.Dispose()} }
function Get-RuntimeManifest {
    $m=(Read-Utf8NoBomText $ManifestPath | ConvertFrom-Json);$entries=@($m.entries)
    if($entries.Count -ne 24){throw "Expected 24 runtime payload entries, got $($entries.Count)."}
    $seen=@{};$out=@()
    foreach($e in $entries){$a=Get-NormalizedArchivePath ([string]$e.path);if(-not $a.StartsWith('resources/app/')){throw "Manifest path lacks resources/app prefix: $a"};if($seen.ContainsKey($a)){throw "Duplicate manifest path: $a"};$seen[$a]=$true;$out+=,[pscustomobject]@{ArchivePath=$a;SourcePath=(Join-Path $ArtifactRoot ($a.Replace([char]'/',[char]$DirectorySeparatorChar)))} }
    return $out
}
function Get-ProductVersionFromText { param([string]$Text) $v=($Text|ConvertFrom-Json).version;if([string]::IsNullOrWhiteSpace([string]$v)){throw 'product.json has no version.'};[string]$v }
function Assert-Artifact {
    $void=Join-Path $ArtifactRoot 'Void.exe';$product=Join-Path $ArtifactRoot (Join-Path 'resources' (Join-Path 'app' 'product.json'))
    foreach($p in @($void,$product)){if(-not (Test-Path -LiteralPath $p -PathType Leaf)){throw "Artifact missing: $p"};if((Get-Item -LiteralPath $p).Length -eq 0){throw "Artifact is empty: $p"};Assert-NotReparsePoint $p|Out-Null}
    $data=Join-Path $ArtifactRoot 'data';if(Test-Path -LiteralPath $data){Assert-NotReparsePoint $data|Out-Null;foreach($bad in @((Join-Path $data 'argv.json'),(Join-Path $data 'user-data'))){if(Test-Path -LiteralPath $bad){throw "Artifact includes generated user data: $bad"}}}
