}
function Assert-PortableArchive {
    param([string]$Path,[int]$RequiredDocsContract=-1,[ValidateSet('current','8ad348e')][string]$RequiredDocsLayout,[switch]$HistoricalArchive)
    $zip=[IO.Compression.ZipFile]::OpenRead($Path)
    try {
        $by=@{};foreach($e in $zip.Entries){$n=Assert-CanonicalArchiveEntryPath $e.FullName;if($by.ContainsKey($n)){throw "Duplicate archive path: $n"};$by[$n]=$e}
        $actual=@($by.Values|ForEach-Object{$_.FullName});foreach($n in @('Void.exe','resources/app/product.json','data/README.txt')){if(-not ($actual -ccontains $n) -or $by[$n].Length -le 0){throw "Portable archive missing or empty: $n"}}
        $userData=@($actual|Where-Object{$_ -clike 'data/user-data/*'});if(($actual -ccontains 'data/argv.json') -or $userData.Count -gt 0){throw 'Portable archive contains test user data.'}
        $s=$by['Void.exe'].Open();try{Assert-X64PeStream $s}finally{$s.Dispose()};$payload=Get-RuntimeManifest
        foreach($x in $payload){if(-not ($actual -ccontains $x.ArchivePath) -or $by[$x.ArchivePath].Length -le 0){throw "Portable archive missing payload: $($x.ArchivePath)"};$s=$by[$x.ArchivePath].Open();try{Assert-X64PeStream $s}finally{$s.Dispose()}}
        $version=Get-ProductVersionFromText (Read-ZipEntryStrictUtf8NoBom $by['resources/app/product.json'])
        $docsArguments=@{EntriesByPath=$by;Manifest=$ReleaseContentManifest;ProductVersion=$version;RequiredContract=$RequiredDocsContract;HistoricalArchive=$HistoricalArchive};if(-not[string]::IsNullOrWhiteSpace($RequiredDocsLayout)){$docsArguments.RequiredLayout=$RequiredDocsLayout};$docs=Assert-ReleaseContentArchiveDocsContract @docsArguments
        [pscustomobject]@{Path=$Path;Size=(Get-Item -LiteralPath $Path).Length;Sha256=(Get-Sha256File $Path);Entries=$by.Count;Version=$version;PayloadCount=$payload.Count;ZipSlipUnsafe=0;DocsContract=$docs.Contract;DocsLayout=$docs.Layout;DocsCount=$docs.Count;Docs=@($docs.Entries)}
    } finally {$zip.Dispose()}
}
function Get-TemplateFiles { @($ReleaseContentManifest.OuterEntries | ForEach-Object { $_.OuterPath }) }
