function Invoke-ReleaseCommand {
    param([string]$Stage,[string]$Name,[string]$FilePath,[string[]]$Arguments,[string]$LogDirectory,$Summary,[string]$SummaryPath,[switch]$AllowNonZero)
    # Only non-secret fixed release arguments are allowed; main must not pass keys or headers.
    $logRoot=Assert-ContainedPath $Stage $LogDirectory;if(-not(Test-Path -LiteralPath $logRoot)){New-Item -ItemType Directory -Path $logRoot -ErrorAction Stop|Out-Null};Assert-NotReparsePoint $logRoot|Out-Null
    $log=Assert-ContainedPath $logRoot (Join-Path $logRoot ($Name+'.log'));$record=[ordered]@{stage=$Stage;name=$Name;filePath=$FilePath;arguments=@($Arguments);startedUtc=[DateTime]::UtcNow.ToString('o');finishedUtc=$null;durationMs=0;exitCode=$null;invocationError=$null;loggingError=$null;summaryError=$null;log=$log;sha256=$null}
    try {$writer=New-Object IO.StreamWriter([IO.File]::Open($log,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read),$Utf8NoBom)}catch{throw [InvalidOperationException]::new(("Release command log creation failed: $Name; $($_.Exception.Message)"),$_.Exception)}
    $watch=[Diagnostics.Stopwatch]::StartNew();$global:LASTEXITCODE=$null;$invocationException=$null;$loggingException=$null;$summaryException=$null;$streamState=[pscustomobject]@{loggingException=$null};$nativeExitCode=$null;$savedErrorActionPreference=$ErrorActionPreference
    try {
        try {
            $ErrorActionPreference='Continue'
            try {& $FilePath @Arguments 2>&1 | ForEach-Object {try {$line=[string]$_;$writer.WriteLine($line);Write-Host $line}catch{$streamState.loggingException=$_.Exception;throw}};$nativeExitCode=$global:LASTEXITCODE}
            catch {if($null -ne $streamState.loggingException){$loggingException=$streamState.loggingException}else{$invocationException=$_.Exception}}
        } finally {$ErrorActionPreference=$savedErrorActionPreference}
        if($null -ne $loggingException){$record.loggingError=$loggingException.ToString();$record.exitCode=-1}
        elseif($null -ne $invocationException){$record.invocationError=$invocationException.ToString();$record.exitCode=-1}
        elseif($null -eq $nativeExitCode){$invocationException=[InvalidOperationException]::new("Native command did not report an exit code: $FilePath");$record.invocationError=$invocationException.ToString();$record.exitCode=-1}
        else {$record.exitCode=[int]$nativeExitCode}
    } finally {
        $watch.Stop();try {$writer.Dispose()}catch{$loggingException=$_.Exception;$record.loggingError=$loggingException.ToString();$record.exitCode=-1};$record.finishedUtc=[DateTime]::UtcNow.ToString('o');$record.durationMs=$watch.ElapsedMilliseconds
        if($null -eq $loggingException){try {$record.sha256=Get-Sha256File $log}catch{$loggingException=$_.Exception;$record.loggingError=$loggingException.ToString();$record.exitCode=-1}}
        try {Add-ReleaseStageRecord $Summary $record $SummaryPath}catch{$summaryException=$_.Exception;$record.summaryError=$summaryException.ToString()}
    }
    if($null -ne $summaryException){throw [InvalidOperationException]::new(("Release command summary failed: $Name; $($summaryException.Message)"),$summaryException)};if($null -ne $loggingException){throw [InvalidOperationException]::new(("Release command logging failed: $Name; $($loggingException.Message)"),$loggingException)};if($null -ne $invocationException){throw [InvalidOperationException]::new(("Release command invocation failed: $Name; $($invocationException.Message)"),$invocationException)};if($record.exitCode -ne 0 -and -not $AllowNonZero){throw "Release command failed: $Name exit $($record.exitCode)"};[pscustomobject]$record
}
function Assert-FocusedExactPassCount {
    param($Record,[int]$Expected)
    $text=Read-Utf8NoBomText $Record.log;$text=[regex]::Replace($text,'\x1B\[[0-?]*[ -/]*[@-~]','');$text=[regex]::Replace($text,'\x1B\][^\x07]*(?:\x07|\x1B\\)','');$text=[regex]::Replace($text,'[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]','')
    if($text -match '(?im)\b(?:0|[1-9][0-9]*)\s+failing\b' -or $text -match '(?im)^\s*BAD\b' -or $text -match '(?im)Failed to resolve module specifier|module load|import.*error'){throw "Focused test reported failure: $($Record.name)"}
    $matches=@([regex]::Matches($text,'(?im)^\s*([0-9]+)\s+passing(?:\s+\([^)]+\))?\s*$'))
    if($matches.Count -ne 1 -or [int]$matches[0].Groups[1].Value -ne $Expected){throw "Focused pass count mismatch for $($Record.name): expected $Expected"}
}
function Get-ExpectedPreHelperFailure {
    param($Record,$Summary,[string]$SummaryPath)
    if($Record.exitCode -eq 0){throw 'Expected pre-helper failure succeeded.'};$text=Read-Utf8NoBomText $Record.log;if(-not $text.Contains('Native runtime payload validation failed')){throw 'Expected pre-helper marker was absent.'};$matches=@([regex]::Matches($text,'(?m)^missing \[([^\]]+)\]: (.+)$'));if($matches.Count -lt 1){throw 'Expected missing payload lines were absent.'};$missing=New-Object Collections.ArrayList;$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($match in $matches){$component=$match.Groups[1].Value.TrimEnd([char]13).Trim();$rawPath=$match.Groups[2].Value.TrimEnd([char]13);if([string]::IsNullOrWhiteSpace($component) -or [string]::IsNullOrWhiteSpace($rawPath) -or $component.IndexOfAny(@([char]13,[char]10)) -ge 0 -or $rawPath.IndexOfAny(@([char]13,[char]10)) -ge 0){throw 'Expected missing payload record is empty or malformed.'};if($rawPath -cnotmatch '^(?:[A-Za-z]:[\\/]|\\\\[^\\/]+[\\/][^\\/]+(?:[\\/]|$))'){throw "Expected missing payload path is not absolute: $rawPath"};try{$fullPath=[IO.Path]::GetFullPath($rawPath)}catch{throw "Expected missing payload path is malformed: $rawPath"};$key=$component+([char]0)+$fullPath;if($seen.Add($key)){[void]$missing.Add([pscustomobject]@{component=$component;path=$fullPath})}};if($missing.Count -lt 1){throw 'Expected missing payload records were empty after normalization.'};$normalized=@($missing);$Summary.missingPayloads=$normalized;Save-ReleaseSummary $Summary $SummaryPath;$normalized
}
function Assert-NonElevated { $id=[Security.Principal.WindowsIdentity]::GetCurrent();$p=New-Object Security.Principal.WindowsPrincipal($id);if($p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevated execution is forbidden.'} }
function Assert-ExecutionPolicy { if((Get-ExecutionPolicy -Scope Process) -ne 'Bypass'){throw 'Process execution policy must be Bypass.'} }
function Get-BuildEnvironment {
    $node=(& node --version 2>&1|Out-String).Trim();$npm=(& npm --version 2>&1|Out-String).Trim();$python=(& python --version 2>&1|Out-String).Trim();$rust=(& rustc --version 2>&1|Out-String).Trim();$msbuild=(& msbuild -version -nologo 2>&1|Out-String).Trim()
    if($node -cne 'v20.18.2'){throw "Unexpected Node: $node"};if($python -notmatch '^Python 3\.10\.11$'){throw "Unexpected Python: $python"};if($rust -notmatch '^rustc 1\.97\.1 '){throw "Unexpected Rust: $rust"};if($msbuild -notmatch '17\.14\.51\.32402'){throw "Unexpected MSBuild: $msbuild"};[pscustomobject]@{node=$node;npm=$npm;python=$python;rustc=$rust;msbuild=$msbuild}
}
function Assert-CommittedCleanHead {
    $head=(& git -C $SourceRoot rev-parse HEAD 2>&1|Out-String).Trim();if($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace($head)){throw 'Unable to read source HEAD.'};$branch=(& git -C $SourceRoot branch --show-current 2>&1|Out-String).Trim();if($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace($branch)){throw 'Unable to read source branch.'};$status=@(& git -C $SourceRoot status --porcelain --untracked-files=all 2>&1);if($LASTEXITCODE -ne 0 -or $status.Count -ne 0){throw 'Source checkout is not committed and clean.'};& git -C $SourceRoot diff --check 2>&1|Out-Null;if($LASTEXITCODE -ne 0){throw 'Source diff check failed.'};[pscustomobject]@{head=$head;branch=$branch;status=@($status)}
}
function Get-ExistingFileMetadata { param([string]$Path) if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return $null};$i=Get-Item -LiteralPath $Path;[pscustomobject]@{path=$i.FullName;size=$i.Length;sha256=(Get-Sha256File $i.FullName);lastWriteUtc=$i.LastWriteTimeUtc.ToString('o')} }
function Test-ExactRetryableError { param([Exception]$Exception) $low=($Exception.HResult -band 0xffff);$low -eq 32 -or $low -eq 33 }
function Invoke-ExactMoveWithRetry {
    param([string]$Source,[string]$Destination,[string]$ExpectedParent)
    $s=Assert-ContainedPath $ExpectedParent $Source;$d=Assert-ContainedPath $ExpectedParent $Destination;Assert-NotReparsePoint $s|Out-Null;for($i=1;$i -le 5;$i++){try{[IO.File]::Move($s,$d);return}catch{if($i -eq 5 -or -not(Test-ExactRetryableError $_.Exception)){throw};Start-Sleep -Milliseconds 250}}
}
function Remove-ExactPathWithRetry {
    param([string]$Path,[string]$ExpectedParent)
    $p=Assert-ContainedPath $ExpectedParent $Path;Assert-NotReparsePoint $p|Out-Null;for($i=1;$i -le 5;$i++){try{$item=Get-Item -LiteralPath $p -Force;if($item.PSIsContainer){Assert-NoReparsePointsInTree $p;[IO.Directory]::Delete($p,$true)}else{Assert-NotReparsePoint $p|Out-Null;[IO.File]::Delete($p)};return}catch{if($i -eq 5 -or -not(Test-ExactRetryableError $_.Exception)){throw};Start-Sleep -Milliseconds 250}}
}
function Assert-NoReleaseResidue {
    param([string]$ExcludeStage)
    $excluded=$null;if($PSBoundParameters.ContainsKey('ExcludeStage')){if([string]::IsNullOrWhiteSpace($ExcludeStage)){throw 'ExcludeStage cannot be empty.'};$excluded=Assert-ContainedPath $PackageRoot $ExcludeStage}
    $names=@('.void-release-win32-x64-*','.void-release-gate-*','.distribution-content-staging-*');$found=@();foreach($pattern in $names){$found+=@(Get-ChildItem -Path $PackageRoot -Force -Filter $pattern|Where-Object{$null -eq $excluded -or -not(Test-SamePhysicalPath $_.FullName $excluded)})};if($found.Count -gt 0){throw "Release residue found: $($found.FullName -join ', ')"}
}
function Get-VoidProcessesByExactPath {
    param([string]$Exe)
    $exact=[IO.Path]::GetFullPath($Exe);@(
        Get-CimInstance Win32_Process | Where-Object { -not [string]::IsNullOrWhiteSpace($_.ExecutablePath) -and ([IO.Path]::GetFullPath($_.ExecutablePath)).Equals($exact,[StringComparison]::OrdinalIgnoreCase) } | ForEach-Object {[pscustomobject]@{pid=[int]$_.ProcessId;parent=[int]$_.ParentProcessId;cmd=[string]$_.CommandLine;path=[string]$_.ExecutablePath}}
    )
}
function Get-AllVoidProcesses { @((Get-CimInstance Win32_Process | Where-Object { $_.Name -ceq 'Void.exe' } | ForEach-Object {[pscustomobject]@{pid=[int]$_.ProcessId;parent=[int]$_.ParentProcessId;cmd=[string]$_.CommandLine;path=[string]$_.ExecutablePath}})) }
function Get-FileEvidence { param([string]$Path) if(Test-Path -LiteralPath $Path -PathType Leaf){Get-ExistingFileMetadata $Path}else{$null} }
function Get-SmokeLogCounters {
    param([string]$Text)
    $fatal=[ordered]@{
        'fatal-line'='(?im)^\s*fatal(?:\s+(?:line|error))?\b.*$'
        'contextual-MODULE_NOT_FOUND'='(?im)^(?=[^\r\n]*(?:fatal|error|crash|uncaught))(?=[^\r\n]*MODULE_NOT_FOUND)[^\r\n]*$'
        'contextual-LifecycleKill'='(?im)^(?=[^\r\n]*(?:fatal|error|crash|uncaught))(?=[^\r\n]*LifecycleKill)[^\r\n]*$'
        'contextual-cannot-find-module'='(?im)^(?=[^\r\n]*(?:fatal|error|crash|uncaught))(?=[^\r\n]*Cannot find module)[^\r\n]*$'
        'ERR_DLOPEN_FAILED'='ERR_DLOPEN_FAILED'
        'invalid-win32-application'='(?im)not a valid Win32 application'
        'uncaught-exception'='(?im)uncaught exception'
        'process-crashed'='(?im)process crashed'
        'renderer-crashed'='(?im)renderer crashed'
    }
    $warning=[ordered]@{
        'MODULE_NOT_FOUND-occurrence'='MODULE_NOT_FOUND'
        'LifecycleKill-occurrence'='LifecycleKill'
        'cannot-find-module-occurrence'='(?im)Cannot find module'
        'warning-line'='(?im)warning'
        'disable-crash-reporter'='disable-crash-reporter'
        'settings-json-enoent'='(?im)settings\.json.*ENOENT'
    }
    $counts=[ordered]@{fatal=[ordered]@{};warning=[ordered]@{}}
    foreach($name in $fatal.Keys){$counts.fatal[$name]=[regex]::Matches($Text,$fatal[$name]).Count};foreach($name in $warning.Keys){$counts.warning[$name]=[regex]::Matches($Text,$warning[$name]).Count};[pscustomobject]$counts
}
function Invoke-ControlledSearchProbeCommand {
    param([string]$Stage,[string]$Name,[string]$Exe,[string]$Probe,[string]$Root,[string]$Query,[ValidateSet('pathname','content')][string]$Kind,[string]$BundledRipgrep,$Summary,[string]$SummaryPath,[switch]$AllowNonZero)
    $arguments=@($Probe,'--root',$Root,'--query',$Query,'--kind',$Kind,'--bundled-rg',$BundledRipgrep);Assert-CanonicalCommandArguments $Exe $arguments;$record=Invoke-ReleaseCommand -Stage $Stage -Name $Name -FilePath $Exe -Arguments $arguments -LogDirectory (Join-Path $Stage 'logs') -Summary $Summary -SummaryPath $SummaryPath -AllowNonZero:$AllowNonZero
    $text=(Read-Utf8NoBomText $record.log).Trim();try{$result=$text|ConvertFrom-Json}catch{throw "Controlled Search probe did not return one JSON object: $Name"};[pscustomobject]@{record=$record;result=$result;text=$text}
}
function Assert-ControlledSearchProbeSuccess {
    param($ProbeResult,[string]$ExpectedTrace,[string]$ExpectedPath)
    $names=@($ProbeResult.result.PSObject.Properties.Name|Sort-Object);if(($names -join ',') -cne 'hasMore,ok,paths,trace'){throw 'Controlled Search success probe exposed unexpected fields.'};if(-not[bool]$ProbeResult.result.ok -or [string]$ProbeResult.result.trace -cne $ExpectedTrace -or [bool]$ProbeResult.result.hasMore){throw "Controlled Search probe returned an unexpected success result: $ExpectedTrace"};$paths=@($ProbeResult.result.paths);if($paths.Count -ne 1 -or -not(Test-SamePhysicalPath ([string]$paths[0]) $ExpectedPath)){throw "Controlled Search probe did not return the exact fixture path: $ExpectedTrace"};if($ProbeResult.text -match '(?i)"(?:command|arguments|executable|stderr|stdout)"'){throw 'Controlled Search probe leaked process detail.'};[pscustomobject]@{trace=$ExpectedTrace;paths=$paths.Count;hasMore=$false}
}
function Assert-ControlledSearchProbeUnavailable {
    param($ProbeResult)
    $names=@($ProbeResult.result.PSObject.Properties.Name|Sort-Object);if(($names -join ',') -cne 'code,ok,trace'){throw 'Controlled Search unavailable probe exposed unexpected fields.'};if([bool]$ProbeResult.result.ok -or [string]$ProbeResult.result.code -cne 'search_backend_unavailable' -or [string]$ProbeResult.result.trace -cne 'terminal-fallback-unavailable' -or [int]$ProbeResult.record.exitCode -eq 0){throw 'Controlled Search unavailable probe did not return the stable structured error.'};if($ProbeResult.text -match '(?i)"(?:command|arguments|executable|stderr|stdout)"'){throw 'Controlled Search unavailable probe leaked process detail.'};[pscustomobject]@{trace='terminal-fallback-unavailable';code='search_backend_unavailable'}
