        try{$primaryExists=Test-Path -LiteralPath $bundled -PathType Leaf;$backupExists=Test-Path -LiteralPath $backup -PathType Leaf;if(-not $primaryExists -and $backupExists){Invoke-ExactMoveWithRetry $backup $bundled $bundledParent;$primaryExists=$true;$backupExists=$false};if(-not $primaryExists -or $backupExists){throw 'Bundled ripgrep restore state was not exactly primary-present and backup-absent.'};Assert-NotReparsePoint $bundled|Out-Null;Assert-X64PeFile $bundled;if((Get-Item -LiteralPath $bundled).Length -ne $bundledSize -or (Get-Sha256File $bundled) -cne $bundledHash){throw 'Bundled ripgrep restore hash mismatch.'}}catch{[void]$restoreErrors.Add("bundled restore: $($_.Exception.ToString())")}
