                    [void]$publication.rollbackPhases.Add([pscustomobject]@{phase='inner-actual-state-restored';utc=[DateTime]::UtcNow.ToString('o')})
                } catch {[void]$publication.rollbackErrors.Add("inner rollback audit: $($_.Exception.ToString())")}
            } else {[void]$publication.rollbackPhases.Add([pscustomobject]@{phase='inner-forward-not-attempted';utc=[DateTime]::UtcNow.ToString('o')})}
