}
function Assert-StrictReleaseSummaryFile {
    param([string]$Path)
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw "Release summary is missing: $Path"};Assert-NotReparsePoint $Path|Out-Null;$text=Read-Utf8NoBomText $Path;try{$value=$text|ConvertFrom-Json}catch{throw "Release summary is not strict JSON: $Path"};if([int]$value.schemaVersion -ne 1 -or [string]::IsNullOrWhiteSpace([string]$value.sourceHead) -or [string]::IsNullOrWhiteSpace([string]$value.status)){throw "Release summary is missing required fields: $Path"};$status=[string]$value.status;$allowedStatuses=@('running','publication-committed-cleanup-pending','passed','failed','failed-after-publication');if($allowedStatuses -cnotcontains $status){throw "Release summary has an unsupported status '$status': $Path"};$terminalStatuses=@('passed','failed','failed-after-publication');[pscustomobject]@{path=(Get-Item -LiteralPath $Path).FullName;size=(Get-Item -LiteralPath $Path).Length;sha256=(Get-Sha256File $Path);status=$status;terminal=($terminalStatuses -ccontains $status);success=($status -ceq 'passed');sourceHead=[string]$value.sourceHead;value=$value}
